def populate_angular_sheet(filepath):
    wb = openpyxl.load_workbook(filepath)
    if "angular" not in wb.sheetnames:
        raise ValueError(f"'angular' sheet not found in {filepath}")

    ws = wb["angular"]
    print(f"Loaded '{filepath}', sheet: 'angular' (rows: {ws.max_row}, cols: {ws.max_column})")

    updated_rows = 0
    updated_cells = 0

    font = Font(name="Calibri", size=11, bold=False)
    alignment = Alignment(wrap_text=True, vertical="center")

    thin_border = Border(
        left=Side(style="thin", color="D3D3D3"),
        right=Side(style="thin", color="D3D3D3"),
        top=Side(style="thin", color="D3D3D3"),
        bottom=Side(style="thin", color="D3D3D3"),
    )

    for r in range(2, ws.max_row + 1):
        yaml_file = ws.cell(r, 3).value
        if not yaml_file or yaml_file not in DATA:
            print(f"Skipping row {r} (yaml: {yaml_file})")
            continue

        row_data = DATA[yaml_file]
        for col_idx in range(7, 32):
            if col_idx in row_data:
                cell = ws.cell(r, col_idx)
                cell.value = row_data[col_idx]
                cell.font = font
                cell.alignment = alignment
                cell.border = thin_border
                updated_cells += 1

        updated_rows += 1
        print(f"Populated row {r}: {yaml_file} (25 columns)")

    wb.save(filepath)
    print(f"\n[SUCCESS] Successfully populated {updated_cells} cells across {updated_rows} rows in {filepath}")


if __name__ == "__main__":
    populate_angular_sheet("workflow-fixes/pipeline_result.xlsx")
